@GameTestHolder("realmeconomy") @PrefixGameTestTemplate(false)
public final class ServiceGameTests {
 private static boolean wallet(){return ChroniclesBridge.loaded();}
 private static BlockPos open(TradeFixture f,Block block){var pos=f.h.absolutePos(new BlockPos(3,2,3));f.h.getLevel().setBlock(pos,block.defaultBlockState(),3);f.player.closeContainer();f.player.setPos(pos.getX()+.5,pos.getY(),pos.getZ()-1);Services.open(f.player,pos);return pos;}
 private static JsonObject request(TradeFixture f){var v=Services.snapshot(f.player);var p=new JsonObject();p.add("nonce",v.get("nonce"));p.add("quote",v.get("quote"));return p;}
 private static void preview(TradeFixture f,int[] slots,String name,boolean rename,int choice){var p=request(f);var a=new JsonArray();for(int i=0;i<4;i++)a.add(i<slots.length?slots[i]:-1);p.add("slots",a);p.addProperty("name",name);p.addProperty("rename",rename);p.addProperty("choice",choice);p.addProperty("secondary",0);Services.action(f.player,"svcPreview",p.toString());}
 private static void confirm(TradeFixture f){Services.action(f.player,"svcConfirm",request(f).toString());}
 private static long paid(TradeFixture f){var receipt=f.player.getPersistentData().getCompound(TradeJournal.RECEIPT_KEY);return receipt.getLong("before")-receipt.getLong("after");}
 private static void sword(TradeFixture f){var sword=new ItemStack(Items.IRON_SWORD);sword.setDamageValue(150);f.player.getInventory().setItem(0,sword);f.player.getInventory().setItem(1,new ItemStack(Items.IRON_INGOT,3));}
 private static void brew(TradeFixture f){f.player.getInventory().setItem(0,PotionContents.createItemStack(Items.POTION,Potions.WATER));f.player.getInventory().setItem(1,PotionContents.createItemStack(Items.POTION,Potions.WATER));f.player.getInventory().setItem(2,new ItemStack(Items.NETHER_WART,2));f.player.getInventory().setItem(3,new ItemStack(Items.BLAZE_POWDER));}
 private static void makeReady(TradeFixture f)throws Exception{var root=f.data.snapshot();var jobs=root.getCompound("jobs");for(String key:jobs.getAllKeys())jobs.getCompound(key).putLong("readyAt",System.currentTimeMillis()-1);Field field=EconomyData.class.getDeclaredField("root");field.setAccessible(true);field.set(f.data,root);}
 private static void policy(TradeFixture f,String operation,String kind,long value,int tax){var p=request(f);p.addProperty("service",kind);p.addProperty("value",value);p.addProperty("tax",tax);Services.action(f.player,operation,p.toString());}
 @GameTest(template="trade_empty",timeoutTicks=100) public static void anvilRepairUsesNativeMaterialCountsAndNeverConsumesXp(GameTestHelper h){try(var f=new TradeFixture(h)){sword(f);open(f,Blocks.ANVIL);preview(f,new int[]{0,1},"",false,0);var q=Services.snapshot(f.player);long cost=q.get("total").getAsLong();if(wallet()){confirm(f);h.assertTrue(paid(f)==cost&&f.player.experienceLevel==0&&f.player.getInventory().getItem(0).getDamageValue()<150&&f.player.getInventory().countItem(Items.IRON_INGOT)<3,"Anvil repair lost XP, components or material counts");}else{confirm(f);h.assertTrue(f.player.getInventory().getItem(0).getDamageValue()==150,"A wallet-free service succeeded");}}h.succeed();}
 @GameTest(template="trade_empty",timeoutTicks=100) public static void renameChargesExactlyOnceAndKeepsTheChosenName(GameTestHelper h){if(!wallet()){h.succeed();return;}try(var f=new TradeFixture(h)){f.player.getInventory().setItem(0,new ItemStack(Items.IRON_SWORD));open(f,Blocks.ANVIL);preview(f,new int[]{0},"Crownblade",true,0);var replay=request(f);confirm(f);long after=ChroniclesBridge.balance(f.player);Services.action(f.player,"svcConfirm",replay.toString());h.assertTrue(f.player.getInventory().getItem(0).getHoverName().getString().equals("Crownblade")&&paid(f)==100&&ChroniclesBridge.balance(f.player)==after,"Rename replay charged or lost the name");}h.succeed();}
 @GameTest(template="trade_empty",timeoutTicks=100) public static void existingCustomNamesSurviveARepairWithoutARenameRequest(GameTestHelper h){if(!wallet()){h.succeed();return;}try(var f=new TradeFixture(h)){sword(f);f.player.getInventory().getItem(0).set(DataComponents.CUSTOM_NAME,Component.literal("Heirloom"));open(f,Blocks.ANVIL);preview(f,new int[]{0,1},"",false,0);confirm(f);h.assertTrue(f.player.getInventory().getItem(0).getHoverName().getString().equals("Heirloom"),"A repair silently removed a name");}h.succeed();}
 @GameTest(template="trade_empty",timeoutTicks=100) public static void enchantmentsRequireLapisButNoExperienceAndPersistTheNewSeed(GameTestHelper h)throws Exception{if(!wallet()){h.succeed();return;}try(var f=new TradeFixture(h)){f.player.getInventory().setItem(0,new ItemStack(Items.BOOK));f.player.getInventory().setItem(1,new ItemStack(Items.LAPIS_LAZULI,3));open(f,Blocks.ENCHANTING_TABLE);int seed=f.player.getEnchantmentSeed();preview(f,new int[]{0},"",false,0);h.assertTrue(Services.snapshot(f.player).get("canConfirm").getAsBoolean(),"No funded enchantment quote at zero XP");confirm(f);h.assertTrue(f.player.experienceLevel==0&&f.player.getInventory().countItem(Items.ENCHANTED_BOOK)==1&&f.player.getInventory().countItem(Items.LAPIS_LAZULI)==2&&f.player.getEnchantmentSeed()!=seed,"XP substitution, lapis or seed failed");var intent=new CompoundTag();intent.putUUID("id",f.player.getPersistentData().getCompound(TradeJournal.RECEIPT_KEY).getUUID("id"));var saved=NbtIo.readCompressed(f.player.getServer().getWorldPath(net.minecraft.world.level.storage.LevelResource.PLAYER_DATA_DIR).resolve(f.player.getUUID()+".dat"),NbtAccounter.unlimitedHeap());h.assertTrue(saved.getInt("XpSeed")==f.player.getEnchantmentSeed(),"Enchantment seed did not reach the player file");}System.out.println("ECONOMY_ENCHANTMENT_PASSED");h.succeed();}
 @GameTest(template="trade_empty",timeoutTicks=100) public static void missingLapisNeverChargesOrRerollsTheSeed(GameTestHelper h){try(var f=new TradeFixture(h)){f.player.getInventory().setItem(0,new ItemStack(Items.BOOK));int seed=f.player.getEnchantmentSeed();open(f,Blocks.ENCHANTING_TABLE);preview(f,new int[]{0},"",false,0);confirm(f);h.assertTrue(f.player.getInventory().countItem(Items.BOOK)==1&&f.player.getEnchantmentSeed()==seed&&f.data.journal()==null,"Missing lapis consumed an item or seed");}h.succeed();}
 @GameTest(template="trade_empty",timeoutTicks=100) public static void aFullInventoryRejectsEnchantingBeforeMoneyOrMaterialsMove(GameTestHelper h){try(var f=new TradeFixture(h)){for(int i=0;i<36;i++)f.player.getInventory().setItem(i,new ItemStack(Items.COBBLESTONE,64));f.player.getInventory().setItem(0,new ItemStack(Items.BOOK,64));f.player.getInventory().setItem(1,new ItemStack(Items.LAPIS_LAZULI,64));open(f,Blocks.ENCHANTING_TABLE);preview(f,new int[]{0},"",false,0);confirm(f);h.assertTrue(f.player.getInventory().countItem(Items.BOOK)==64&&f.player.getInventory().countItem(Items.LAPIS_LAZULI)==64&&f.data.journal()==null,"A full inventory lost enchantment inputs");}h.succeed();}
 @GameTest(template="trade_empty",timeoutTicks=100) public static void smithingUsesTheVanillaTemplateAndMaterials(GameTestHelper h){if(!wallet()){h.succeed();return;}try(var f=new TradeFixture(h)){f.player.getInventory().setItem(0,new ItemStack(Items.NETHERITE_UPGRADE_SMITHING_TEMPLATE));f.player.getInventory().setItem(1,new ItemStack(Items.DIAMOND_SWORD));f.player.getInventory().setItem(2,new ItemStack(Items.NETHERITE_INGOT));open(f,Blocks.SMITHING_TABLE);preview(f,new int[]{0,1,2},"",false,0);confirm(f);h.assertTrue(f.player.getInventory().countItem(Items.NETHERITE_SWORD)==1&&f.player.getInventory().countItem(Items.NETHERITE_INGOT)==0&&f.player.getInventory().countItem(Items.NETHERITE_UPGRADE_SMITHING_TEMPLATE)==0&&paid(f)==1000,"Smithing skipped a template, charged wrongly or lost output");}h.succeed();}
 @GameTest(template="trade_empty",timeoutTicks=100) public static void missingSmithingTemplateDoesNotCharge(GameTestHelper h){try(var f=new TradeFixture(h)){f.player.getInventory().setItem(1,new ItemStack(Items.DIAMOND_SWORD));f.player.getInventory().setItem(2,new ItemStack(Items.NETHERITE_INGOT));open(f,Blocks.SMITHING_TABLE);preview(f,new int[]{-1,1,2},"",false,0);confirm(f);h.assertTrue(f.player.getInventory().countItem(Items.DIAMOND_SWORD)==1&&f.data.journal()==null,"An invalid smithing recipe mutated items");}h.succeed();}
 @GameTest(template="trade_empty",timeoutTicks=100) public static void changedInputsInvalidateTheOldQuoteBeforeCharging(GameTestHelper h){if(!wallet()){h.succeed();return;}try(var f=new TradeFixture(h)){sword(f);open(f,Blocks.ANVIL);preview(f,new int[]{0,1},"",false,0);f.player.getInventory().setItem(1,ItemStack.EMPTY);confirm(f);h.assertTrue(ChroniclesBridge.balance(f.player)==100000&&f.player.getInventory().getItem(0).getDamageValue()==150,"A stale material quote was charged");}h.succeed();}
 @GameTest(template="trade_empty",timeoutTicks=100) public static void negativeOrInjectedPricesAreRejectedByTheServiceProtocol(GameTestHelper h){try(var f=new TradeFixture(h)){sword(f);open(f,Blocks.ANVIL);preview(f,new int[]{0,1},"",false,0);var p=request(f);p.addProperty("total",-1000);Services.action(f.player,"svcConfirm",p.toString());h.assertTrue(f.player.getInventory().getItem(0).getDamageValue()==150&&f.data.journal()==null,"A client-injected price succeeded");}h.succeed();}
 @GameTest(template="trade_empty",timeoutTicks=100) public static void serviceMenusContainNoNativeResultSlotsToBypassPayments(GameTestHelper h){try(var f=new TradeFixture(h)){open(f,Blocks.ANVIL);h.assertTrue(f.player.containerMenu.slots.isEmpty(),"A native result slot bypasses payment");}h.succeed();}
 @GameTest(template="trade_empty",timeoutTicks=100) public static void rawAnvilResultsRemainBlockedUntilTheAdministratorDisablesTheSystem(GameTestHelper h){try(var f=new TradeFixture(h)){var pos=open(f,Blocks.ANVIL);var nativeMenu=new AnvilMenu(-1,f.player.getInventory(),ContainerLevelAccess.create(h.getLevel(),pos));nativeMenu.getSlot(0).set(new ItemStack(Items.IRON_SWORD));nativeMenu.setItemName("Guard test");f.player.experienceLevel=100;h.assertTrue(!nativeMenu.getSlot(2).mayPickup(f.player),"A raw anvil bypassed the paid system");var r=f.data.rule(ServiceKind.ANVIL_REPAIR);f.data.changeRule(f.player.getUUID(),"Admin",ServiceKind.ANVIL_REPAIR,r.limits(r.minimum(),r.maximum(),r.taxCap(),false));h.assertTrue(nativeMenu.getSlot(2).mayPickup(f.player),"Disabled anvil did not restore Vanilla XP behavior");}h.succeed();}
 @GameTest(template="trade_empty",timeoutTicks=100) public static void rawEnchantmentPacketsCannotConsumeLapisOrEnchantForFree(GameTestHelper h){try(var f=new TradeFixture(h)){var pos=open(f,Blocks.ENCHANTING_TABLE);var nativeMenu=new EnchantmentMenu(-1,f.player.getInventory(),ContainerLevelAccess.create(h.getLevel(),pos));nativeMenu.getSlot(0).set(new ItemStack(Items.BOOK));nativeMenu.getSlot(1).set(new ItemStack(Items.LAPIS_LAZULI,3));f.player.experienceLevel=100;h.assertTrue(!nativeMenu.clickMenuButton(f.player,0)&&nativeMenu.getSlot(0).getItem().is(Items.BOOK),"Raw enchanting bypassed the wallet");}h.succeed();}
 @GameTest(template="trade_empty",timeoutTicks=100) public static void brewingKeepsIngredientsFuelAndTheTwentySecondBatch(GameTestHelper h){if(!wallet()){h.succeed();return;}try(var f=new TradeFixture(h)){brew(f);open(f,Blocks.BREWING_STAND);preview(f,new int[]{0,1,-1,2},"",false,0);confirm(f);var jobs=f.data.collection("jobs");h.assertTrue(jobs.size()==1&&f.data.collection("fuel").getCompound(f.player.getUUID().toString()).getInt("units")==19&&paid(f)==500&&f.player.getInventory().countItem(Items.POTION)==0&&f.player.getInventory().countItem(Items.NETHER_WART)==1,"Brewing input escrow/fuel/price failed");var job=jobs.getCompound(jobs.getAllKeys().iterator().next());h.assertTrue(job.getList("items",Tag.TAG_COMPOUND).size()==2&&job.getLong("readyAt")>System.currentTimeMillis()+15000,"Batch timing or bottle count failed");}h.succeed();}
 @GameTest(template="trade_empty",timeoutTicks=100) public static void brewingCannotStartWithoutFuel(GameTestHelper h){try(var f=new TradeFixture(h)){brew(f);f.player.getInventory().setItem(3,ItemStack.EMPTY);open(f,Blocks.BREWING_STAND);preview(f,new int[]{0,1,-1,2},"",false,0);confirm(f);h.assertTrue(f.data.collection("jobs").isEmpty()&&f.player.getInventory().countItem(Items.POTION)==2,"Brewing without fuel consumed bottles");}h.succeed();}
 @GameTest(template="trade_empty",timeoutTicks=100) public static void automatedVanillaBrewingCannotBypassThePaidBatch(GameTestHelper h){try(var f=new TradeFixture(h)){var pos=open(f,Blocks.BREWING_STAND);var stand=(net.minecraft.world.level.block.entity.BrewingStandBlockEntity)h.getLevel().getBlockEntity(pos);stand.setItem(0,PotionContents.createItemStack(Items.POTION,Potions.WATER));stand.setItem(3,new ItemStack(Items.NETHER_WART));stand.setItem(4,new ItemStack(Items.BLAZE_POWDER));for(int i=0;i<450;i++)net.minecraft.world.level.block.entity.BrewingStandBlockEntity.serverTick(h.getLevel(),pos,h.getLevel().getBlockState(pos),stand);h.assertTrue(stand.getItem(3).getCount()==1&&stand.getItem(4).getCount()==1&&stand.getItem(0).get(DataComponents.POTION_CONTENTS).is(Potions.WATER),"Unfunded automated brewing bypassed payment");}h.succeed();}
 @GameTest(template="trade_empty",timeoutTicks=100) public static void aCompletedBatchCanOnlyBeCollectedOnce(GameTestHelper h)throws Exception{if(!wallet()){h.succeed();return;}try(var f=new TradeFixture(h)){brew(f);open(f,Blocks.BREWING_STAND);preview(f,new int[]{0,1,-1,2},"",false,0);confirm(f);makeReady(f);var p=request(f);p.addProperty("job",f.data.collection("jobs").getAllKeys().iterator().next());Services.action(f.player,"svcClaim",p.toString());Services.action(f.player,"svcClaim",p.toString());h.assertTrue(f.player.getInventory().countItem(Items.POTION)==2&&f.data.collection("jobs").isEmpty(),"A batch replay duplicated potions");for(var item:f.player.getInventory().items)if(item.is(Items.POTION))h.assertTrue(item.get(DataComponents.POTION_CONTENTS).is(Potions.AWKWARD),"The native potion recipe changed");}System.out.println("ECONOMY_BREWING_PASSED");h.succeed();}
 @GameTest(template="trade_empty",timeoutTicks=100) public static void anotherPlayerCannotClaimAnEscrowedBatch(GameTestHelper h)throws Exception{if(!wallet()){h.succeed();return;}try(var f=new TradeFixture(h)){brew(f);var pos=open(f,Blocks.BREWING_STAND);preview(f,new int[]{0,1,-1,2},"",false,0);confirm(f);makeReady(f);f.other.setPos(f.player.position());Services.open(f.other,pos);var v=Services.snapshot(f.other);var p=new JsonObject();p.add("nonce",v.get("nonce"));p.add("quote",v.get("quote"));p.addProperty("job",f.data.collection("jobs").getAllKeys().iterator().next());Services.action(f.other,"svcClaim",p.toString());h.assertTrue(f.data.collection("jobs").size()==1&&f.other.getInventory().countItem(Items.POTION)==0,"Another player stole a paid batch");}h.succeed();}
 @GameTest(template="trade_empty",timeoutTicks=100) public static void anUnfinishedBatchCannotBeCollectedEarly(GameTestHelper h){if(!wallet()){h.succeed();return;}try(var f=new TradeFixture(h)){brew(f);open(f,Blocks.BREWING_STAND);preview(f,new int[]{0,1,-1,2},"",false,0);confirm(f);var p=request(f);p.addProperty("job",f.data.collection("jobs").getAllKeys().iterator().next());Services.action(f.player,"svcClaim",p.toString());h.assertTrue(f.data.collection("jobs").size()==1&&f.player.getInventory().countItem(Items.POTION)==0,"A batch completed before its timer");}h.succeed();}
 @GameTest(template="trade_empty",timeoutTicks=100) public static void theDeskCanCollectABatchAfterItsOriginalStandIsGone(GameTestHelper h)throws Exception{if(!wallet()){h.succeed();return;}try(var f=new TradeFixture(h)){brew(f);var pos=open(f,Blocks.BREWING_STAND);preview(f,new int[]{0,1,-1,2},"",false,0);confirm(f);makeReady(f);f.player.closeContainer();h.getLevel().removeBlock(pos,false);open(f,EconomyBlocks.DESK.get());var p=request(f);p.addProperty("job",f.data.collection("jobs").getAllKeys().iterator().next());Services.action(f.player,"svcClaim",p.toString());h.assertTrue(f.data.collection("jobs").isEmpty()&&f.player.getInventory().countItem(Items.POTION)==2,"Breaking a stand destroyed the paid potions");}h.succeed();}
 @GameTest(template="trade_empty",timeoutTicks=100) public static void theDeskRejectsAnUnswornPresidentAndExpiresPermissionsImmediately(GameTestHelper h){if(!CouncilFixture.loaded()){h.succeed();return;}try(var council=new CouncilFixture(h.getLevel().getServer());var f=new TradeFixture(h)){long now=System.currentTimeMillis();council.mandate(f.player.getUUID(),now-1000,now+60000,0);open(f,EconomyBlocks.DESK.get());policy(f,"svcPolicy","VILLAGER",700,1000);h.assertTrue(f.data.rule(ServiceKind.VILLAGER).value()==500,"An unsworn winner changed conversion");council.claim(now-1);policy(f,"svcPolicy","VILLAGER",700,1000);h.assertTrue(f.data.rule(ServiceKind.VILLAGER).value()==700,"Sworn President could not change conversion");council.expire(now-1);policy(f,"svcPolicy","VILLAGER",900,1200);h.assertTrue(f.data.rule(ServiceKind.VILLAGER).value()==700,"Expired President retained economic authority");}h.succeed();}
 @GameTest(template="trade_empty",timeoutTicks=100) public static void administratorBoundsAndServiceSwitchAreLoggedTogether(GameTestHelper h){try(var f=new TradeFixture(h)){f.op(f.player);open(f,EconomyBlocks.DESK.get());var p=request(f);p.addProperty("service","ANVIL_REPAIR");p.addProperty("minimum",150);p.addProperty("maximum",200);p.addProperty("cap",500);p.addProperty("enabled",false);Services.action(f.player,"svcAdmin",p.toString());var r=f.data.rule(ServiceKind.ANVIL_REPAIR);h.assertTrue(r.value()==150&&r.minimum()==150&&r.maximum()==200&&!r.enabled()&&!f.data.rule(ServiceKind.ANVIL_COMBINE).enabled()&&f.data.audit().size()==3,"Administrative bounds/switch audit was incomplete");}h.succeed();}
 @GameTest(template="trade_empty",timeoutTicks=100) public static void priceChangesInvalidateAQuoteWithoutCharging(GameTestHelper h){if(!wallet()){h.succeed();return;}try(var f=new TradeFixture(h)){sword(f);open(f,Blocks.ANVIL);preview(f,new int[]{0,1},"",false,0);var r=f.data.rule(ServiceKind.ANVIL_REPAIR);f.data.changeRule(f.other.getUUID(),"President",ServiceKind.ANVIL_REPAIR,r.price(300,0));confirm(f);h.assertTrue(ChroniclesBridge.balance(f.player)==100000&&f.player.getInventory().getItem(0).getDamageValue()==150,"A hidden price change was charged");}h.succeed();}
 @GameTest(template="trade_empty",timeoutTicks=100) public static void aBrokenServiceBlockInvalidatesItsSession(GameTestHelper h){try(var f=new TradeFixture(h)){sword(f);var pos=open(f,Blocks.ANVIL);preview(f,new int[]{0,1},"",false,0);var pending=request(f);h.getLevel().removeBlock(pos,false);Services.action(f.player,"svcConfirm",pending.toString());h.assertTrue(f.player.getInventory().getItem(0).getDamageValue()==150&&f.data.journal()==null,"A destroyed station still sold a service");}h.succeed();}
 @GameTest(template="trade_empty",timeoutTicks=100) public static void realmAdminProvidersCanAuthorizePlayersWithoutVanillaOp(GameTestHelper h)throws Exception{Field field=EconomyPermissions.class.getDeclaredField("provider");field.setAccessible(true);Object old=field.get(null);try(var f=new TradeFixture(h)){field.set(null,null);EconomyPermissions.register(p->p.getUUID().equals(f.player.getUUID()));h.assertTrue(!f.player.hasPermissions(2)&&EconomyPermissions.canAdminister(f.player)&&!EconomyPermissions.canAdminister(f.other),"Realm Admin provider fell back to OP or authorized another player");open(f,EconomyBlocks.DESK.get());var p=request(f);p.addProperty("seconds",900);Services.action(f.player,"svcPeriod",p.toString());h.assertTrue(f.data.beaconSeconds()==900,"A delegated non-OP administrator could not set the period");}finally{field.set(null,old);}System.out.println("ECONOMY_PERMISSIONS_PASSED");h.succeed();}
 @GameTest(template="trade_empty",timeoutTicks=100) public static void aFailingPermissionProviderNeverFallsBackToOp(GameTestHelper h)throws Exception{Field field=EconomyPermissions.class.getDeclaredField("provider");field.setAccessible(true);Object old=field.get(null);try(var f=new TradeFixture(h)){f.op(f.player);field.set(null,null);EconomyPermissions.register(p->{throw new IllegalStateException("Provider unavailable");});h.assertTrue(!EconomyPermissions.canAdminister(f.player),"Provider failure exposed an OP fallback");}finally{field.set(null,old);}h.succeed();}
 @GameTest(template="trade_empty",timeoutTicks=100) public static void serviceTaxCreditsTheActualCrownAndNeverThePresident(GameTestHelper h)throws Exception{if(!wallet()||!CrownBridge.installed()){h.succeed();return;}try(var crown=new TaxGameTests.Crown(h);var f=new TradeFixture(h)){var r=f.data.rule(ServiceKind.ANVIL_RENAME);f.data.changeRule(f.other.getUUID(),"President",ServiceKind.ANVIL_RENAME,r.price(100,1000));f.player.getInventory().setItem(0,new ItemStack(Items.IRON_SWORD));open(f,Blocks.ANVIL);preview(f,new int[]{0},"Taxed blade",true,0);confirm(f);h.assertTrue(paid(f)==110&&crown.balance()==10&&ChroniclesBridge.balance(f.other)==200000,"Service tax failed its single logical debit or paid the President");}System.out.println("ECONOMY_TAX_INTEGRATION_PASSED");h.succeed();}
 @GameTest(template="trade_empty",timeoutTicks=100) public static void playerFileFailureRecoversTheSameServiceWithoutAnotherCharge(GameTestHelper h)throws Exception{if(!wallet()){h.succeed();return;}try(var f=new TradeFixture(h)){sword(f);open(f,Blocks.ANVIL);preview(f,new int[]{0,1},"",false,0);var file=f.player.getServer().getWorldPath(net.minecraft.world.level.storage.LevelResource.PLAYER_DATA_DIR).resolve(f.player.getUUID()+".dat");Files.createDirectories(file.getParent());Files.deleteIfExists(file);Files.createDirectory(file);confirm(f);h.assertTrue(f.data.journal()!=null,"Interrupted service lost its intent");long beforeRecovery=ChroniclesBridge.balance(f.player);Files.deleteIfExists(file);Files.deleteIfExists(file.resolveSibling(f.player.getUUID()+".dat_old"));TradeJournal.recover(f.player);h.assertTrue(f.data.journal()==null&&ChroniclesBridge.balance(f.player)==beforeRecovery&&f.player.getInventory().countItem(Items.IRON_SWORD)==1&&f.player.getInventory().getItem(0).getDamageValue()<150,"Service recovery repeated a payment or result");}System.out.println("ECONOMY_RECOVERY_PASSED");h.succeed();}
 @GameTest(template="trade_empty",timeoutTicks=100) public static void versionOneKeepsItsVillagerPolicyAndStockDuringMigration(GameTestHelper h)throws Exception{try(var f=new TradeFixture(h)){var old=f.data.snapshot();old.putInt("version",1);for(String key:List.of("rules","jobs","fuel","beacons","audit","beaconSeconds"))old.remove(key);old.putInt("rate",1200);var ctor=EconomyData.class.getDeclaredConstructor(Path.class,CompoundTag.class);ctor.setAccessible(true);var migrated=ctor.newInstance(f.directory.resolve("migrated.dat"),old);h.assertTrue(migrated.snapshot().getInt("version")==3&&migrated.rate()==1200&&migrated.rule(ServiceKind.VILLAGER).value()==500,"Migration lost the approved rate or conversion");}h.succeed();}
 @GameTest(template="trade_empty",timeoutTicks=100) public static void theEconomicDeskHasCraftableRegisteredBlockItemAndCreativeTab(GameTestHelper h){h.assertTrue(EconomyBlocks.DESK_ITEM.get() instanceof BlockItem&&EconomyBlocks.TAB.get()!=null,"Economy Desk has no physical item/creative tab");h.assertTrue(h.getLevel().getRecipeManager().byKey(net.minecraft.resources.ResourceLocation.parse("realmeconomy:economy_desk")).isPresent(),"Economy Desk crafting recipe is missing");h.succeed();}
 @GameTest(template="trade_empty",timeoutTicks=100) public static void beaconCannotActivateWithoutItsNormalPyramid(GameTestHelper h){try(var f=new TradeFixture(h)){open(f,Blocks.BEACON);confirm(f);h.assertTrue(f.data.collection("beacons").isEmpty()&&f.data.journal()==null,"Beacon sold effects without a pyramid");}h.succeed();}
 @GameTest(template="trade_empty",timeoutTicks=100) public static void fundedBeaconEffectsExpireAndDoNotEscapeTheirTier(GameTestHelper h)throws Exception{if(!wallet()){h.succeed();return;}try(var f=new TradeFixture(h)){var pos=open(f,Blocks.BEACON);for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++)h.getLevel().setBlock(pos.offset(x,-1,z),Blocks.IRON_BLOCK.defaultBlockState(),2);preview(f,new int[]{},"",false,0);confirm(f);h.assertTrue(f.data.collection("beacons").size()==1&&paid(f)==5000,"Valid beacon activation failed");h.getLevel().addNewPlayer(f.player);BeaconService.apply(h.getLevel(),pos,1);h.assertTrue(f.player.hasEffect(MobEffects.MOVEMENT_SPEED),"Funded beacon did not apply its effect");f.player.removeAllEffects();var root=f.data.snapshot();root.getCompound("beacons").getCompound(BeaconService.key(h.getLevel(),pos)).putLong("until",System.currentTimeMillis()-1);var field=EconomyData.class.getDeclaredField("root");field.setAccessible(true);field.set(f.data,root);BeaconService.apply(h.getLevel(),pos,1);h.assertTrue(!f.player.hasEffect(MobEffects.MOVEMENT_SPEED)&&!BeaconService.unlocked(4,1),"Expired beacon or a locked tier produced free effects");}System.out.println("ECONOMY_BEACON_PASSED");h.succeed();}

 @GameTest(template="trade_empty",timeoutTicks=100) public static void governedConversionActuallyChangesTheNativeVillagerQuote(GameTestHelper h){try(var f=new TradeFixture(h)){var r=f.data.rule(ServiceKind.VILLAGER);f.data.changeRule(f.player.getUUID(),"President",ServiceKind.VILLAGER,r.price(700,0));f.open(f.player);h.assertTrue(f.view(f.player).getAsJsonArray("offers").get(0).getAsJsonObject().get("base").getAsLong()==14000,"Governed conversion did not reach native Villager prices");}h.succeed();}
 @GameTest(template="trade_empty",timeoutTicks=100) public static void disablingVillagerConversionRestoresTheNativeInteraction(GameTestHelper h){try(var f=new TradeFixture(h)){var r=f.data.rule(ServiceKind.VILLAGER);f.data.changeRule(f.player.getUUID(),"Admin",ServiceKind.VILLAGER,r.limits(r.minimum(),r.maximum(),r.taxCap(),false));f.player.setPos(f.merchant.position());var event=new net.neoforged.neoforge.event.entity.player.PlayerInteractEvent.EntityInteract(f.player,net.minecraft.world.InteractionHand.MAIN_HAND,f.merchant);TradingService.interact(event);h.assertTrue(!event.isCanceled(),"Disabled conversion still intercepted Vanilla trading");}h.succeed();}
 @GameTest(template="trade_empty",timeoutTicks=100) public static void interruptedBrewingStartCreatesOneJobAndOneFuelCredit(GameTestHelper h)throws Exception{if(!wallet()){h.succeed();return;}try(var f=new TradeFixture(h)){brew(f);open(f,Blocks.BREWING_STAND);preview(f,new int[]{0,1,-1,2},"",false,0);var file=f.player.getServer().getWorldPath(net.minecraft.world.level.storage.LevelResource.PLAYER_DATA_DIR).resolve(f.player.getUUID()+".dat");Files.createDirectories(file.getParent());Files.deleteIfExists(file);Files.createDirectory(file);confirm(f);h.assertTrue(f.data.journal()!=null&&f.data.collection("jobs").isEmpty(),"Interrupted brewing start lost its prepared intent");long money=ChroniclesBridge.balance(f.player);Files.deleteIfExists(file);Files.deleteIfExists(file.resolveSibling(f.player.getUUID()+".dat_old"));TradeJournal.recover(f.player);h.assertTrue(f.data.collection("jobs").size()==1&&f.data.collection("fuel").getCompound(f.player.getUUID().toString()).getInt("units")==19&&ChroniclesBridge.balance(f.player)==money&&f.player.getInventory().countItem(Items.POTION)==0,"Brewing recovery repeated money, ingredients, job or fuel");}h.succeed();}
 @GameTest(template="trade_empty",timeoutTicks=100) public static void aFullInventoryPreservesTheReadyPotionEscrow(GameTestHelper h)throws Exception{if(!wallet()){h.succeed();return;}try(var f=new TradeFixture(h)){brew(f);open(f,Blocks.BREWING_STAND);preview(f,new int[]{0,1,-1,2},"",false,0);confirm(f);makeReady(f);for(int i=0;i<36;i++)f.player.getInventory().setItem(i,new ItemStack(Items.COBBLESTONE,64));var p=request(f);p.addProperty("job",f.data.collection("jobs").getAllKeys().iterator().next());Services.action(f.player,"svcClaim",p.toString());h.assertTrue(f.data.collection("jobs").size()==1&&f.player.getInventory().countItem(Items.POTION)==0,"A full inventory destroyed or duplicated ready potions");}h.succeed();}
}
